def stripe_transform(grid):
    h, w = len(grid), len(grid[0])
    coords = {
        'r': lambda r,c: r,
        'c': lambda r,c: c,
        'sum': lambda r,c: r+c,
        'diff': lambda r,c: c-r,
    }
    best = None
    for name, fn in coords.items():
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = fn(r,c)
                    groups.setdefault(k, set()).add(color)
        if not groups or any(len(v) != 1 for v in groups.values()):
            continue
        # Prefer the orientation with the longest observed stripe; break ties by total stripe cohesion.
        counts = {k: sum(1 for r in range(h) for c in range(w) if grid[r][c] and fn(r,c)==k) for k in groups}
        score = (max(counts.values()), sum(v*v for v in counts.values()))
        if best is None or score > best[0]:
            best=(score, name, fn, groups)
    if best is None:
        return [row[:] for row in grid]
    _, name, fn, groups=best
    p=len(groups)
    residues={}
    for k, colors in groups.items():
        residues[k%p]=next(iter(colors))
    return [[residues[fn(r,c)%p] for c in range(w)] for r in range(h)]

# Reconstruct demo inputs using their diagonal stripe descriptions.
def stripe_grid(n, tracks, coord):
    g=[[0]*n for _ in range(n)]
    for color, values in tracks.items():
        for k in values:
            for r in range(n):
                for c in range(n):
                    if coord(r,c)==k:
                        g[r][c]=color
    return g

def periodic_output(n, coord, mapping):
    return [[mapping[coord(r,c)%len(mapping)] for c in range(n)] for r in range(n)]

